#include <ESPressio_AdapterQueue.hpp>
#include <cassert>
using namespace ESPressio::Adapters;
using Arena=StaticByteArena<ByteClass<8,16>>;using Domain=StaticCapacityDomain<128,16,Arena>;using Plane=CapacityPlane<AdapterDirection::Outbound,Domain,Domain,Domain,Domain,Domain,Domain,Domain>;
struct R{ByteLease B;int V;R(ByteLease&& b,int v) noexcept:B(std::move(b)),V(v){}};
static CapacityRecordLease Make(Plane& p,AdapterServiceClass service,int v){CapacityReservation r;assert(p.TryAcquireTrusted(service,1,r)==AdapterResourceStatus::Success);assert(r.Bytes().Commit(0)==AdapterResourceStatus::Success);CapacityRecordLease l;assert(p.Construct<R>(std::move(r),l,v)==AdapterResourceStatus::Success);return l;}
int main(){Plane p;p.Initialize();AdapterQueueBank<2,4> bank;bank.Initialize();auto a=Make(p,AdapterServiceClass::Critical,1);auto b=Make(p,AdapterServiceClass::Critical,2);auto c=Make(p,AdapterServiceClass::Responsive,3);assert(bank.TryPush(AdapterServiceClass::Critical,0,std::move(a))==AdapterQueueStatus::Success);assert(bank.TryPush(AdapterServiceClass::Critical,1,std::move(b))==AdapterQueueStatus::Success);assert(bank.TryPush(AdapterServiceClass::Responsive,0,std::move(c))==AdapterQueueStatus::Success);CapacityRecordLease out;assert(bank.TryPopFair(2,out)==AdapterQueueStatus::Success);const auto first=out.Get<R>().V;out.Reset();assert(first==1||first==2);assert(bank.TryPopFair(2,out)==AdapterQueueStatus::Success);assert(out.Get<R>().V==3);out.Reset();assert(bank.TryPopFair(2,out)==AdapterQueueStatus::Success);assert(out.Get<R>().V!=3);out.Reset();assert(bank.TryPopFair(2,out)==AdapterQueueStatus::Empty);}
